def center_text(text, width):
    text_width = wcswidth(text)
    pad = max((width - text_width) // 2, 0)
    return ' ' * pad + text

def play_braille_frames_with_timer(frames, delay=0.05):
    async def _animate():
        start_time = time.time()
        frame_idx = 0
        cols, _ = shutil.get_terminal_size()
        prepared_frames = []
        for frame in frames:
            centered = '\n'.join(center_text(line, cols) for line in str(frame).splitlines())
            prepared_frames.append(centered)
        try:
            while True:
                elapsed = int(time.time() - start_time)
                minutes = elapsed // 60
                seconds = elapsed % 60
                print("\033[2J\033[H", end="")
                print(center_text(f"\033[34m[IN PROGRESS]\033[0m {minutes:02d}:{seconds:02d}", cols))
                print(prepared_frames[frame_idx % len(prepared_frames)])
                frame_idx += 1
                await asyncio.sleep(delay)
        except asyncio.CancelledError:
            pass
    return _animate